-export async function listTools(){return []}export async function callTool(){throw new Error('TODO')}
+import path from 'node:path';
+import fs from 'node:fs';
+
+const DATA_DIR = path.resolve('data');
+
+export async function listTools() {
+  return [
+    {
+      name: 'file_metadata',
+      description:
+        'Return metadata (relative path, byte size, lowercase extension) for a file under the data directory. File contents are never exposed.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          path: {
+            type: 'string',
+            description: 'Path to the file, relative to the data directory.'
+          }
+        },
+        required: ['path'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'file_metadata') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const inputPath = args.path;
+  if (typeof inputPath !== 'string' || inputPath.length === 0) {
+    throw new Error('path is required and must be a non-empty string');
+  }
+
+  const resolved = path.resolve(DATA_DIR, inputPath);
+  if (resolved !== DATA_DIR && !resolved.startsWith(DATA_DIR + path.sep)) {
+    throw new Error('Path traversal outside the data directory is not allowed');
+  }
+
+  let stat;
+  try {
+    stat = fs.statSync(resolved);
+  } catch (e) {
+    throw new Error(`File not found: ${inputPath}`);
+  }
+  if (!stat.isFile()) {
+    throw new Error(`Not a file: ${inputPath}`);
+  }
+
+  const relPath = path.relative(DATA_DIR, resolved);
+  const ext = path.extname(resolved).toLowerCase();
+  const size = stat.size;
+
+  const text = `path: ${relPath}\nsize: ${size}\nextension: ${ext}`;
+
+  return {
+    content: [{ type: 'text', text }]
+  };
+}
